model.modelJson:
{
  "required" : [ "coordinates", "type" ],
  "type" : "object",
  "properties" : {
    "type" : {
      "type" : "string",
      "enum" : [ "Polygon" ]
    },
    "bbox" : {
      "$ref" : "#/components/schemas/BBox"
    },
    "coordinates" : {
      "type" : "array",
      "description" : "A Polygon is a surface specified by its vertices. The vertices are coordinates, given in the decimal degrees unit. Note the following:\n  - The surface vertices are given counterclockwise.\n  - Holes in the surface are given clockwise.\n  - The last and the first coordinates must be equal.\nIn the following it is described, which value of the innermost array represents which coordinate:\n  - Longitude\n  - Latitude\n\nA example, given in the [RFC7946 - The GeoJSON format](https://tools.ietf.org/html/rfc7946#appendix-A.3)\n",
      "example" : [ [ [ 8, 49 ], [ 8.1, 49 ], [ 8.1, 49.1 ], [ 8, 49.1 ], [ 8, 49 ] ], [ [ 8.08, 49.08 ], [ 8.08, 49.02 ], [ 8.02, 49.02 ], [ 8.02, 49.08 ], [ 8.08, 49.08 ] ] ],
      "externalDocs" : {
        "description" : "RFC7946 - The GeoJSON format",
        "url" : "https://tools.ietf.org/html/rfc7946#section-3.1.6"
      },
      "items" : {
        "minItems" : 4,
        "type" : "array",
        "items" : {
          "maxItems" : 2,
          "minItems" : 2,
          "type" : "array",
          "items" : {
            "type" : "number"
          }
        }
      }
    }
  }
}

vars.jsonSchema:
{
  "maxItems" : 4,
  "minItems" : 4,
  "type" : "array",
  "description" : "This parameter contains information on the coordinate range for its Geometries, Features or FeatureCollections. It describes a bounding box for this. The coordinates are given in the decimal degrees unit. In the following it is described, which value of the array represents which coordinate:\n  - The most southwesterly point: Longitude\n  - The most southwesterly point: Latitude\n  - The most northeasterly point: Longitude\n  - The most northeasterly point: Latitude\n",
  "example" : [ 8.01234567890123, 49.0123456789012, 8.12345678901234, 49.1234567890123 ],
  "externalDocs" : {
    "description" : "RFC7946 - The GeoJSON format",
    "url" : "https://tools.ietf.org/html/rfc7946#section-5"
  },
  "items" : {
    "type" : "number"
  }
}

